window.__votdWeek && window.__votdWeek({"week":"2028-03-06","reading":"2 Nephi 26–30","days":[{"d":"2028-03-06","ref":"2 Nephi 26:29","b":"2 Nephi","c":26,"v":29,"he":"צִוָּה כִּי־לֹא תִהְיֶה כְּהֻנַּת־שָׁוְא כִּי הִנֵּה כְּהֻנַּת־שָׁוְא הִיא אֲשֶׁר יַטִּיפוּ אֲנָשִׁים וְיָשִׂימוּ אֶת־נַפְשָׁם לְאוֹר לָעוֹלָם לְמַעַן בֶּצַע וּתְהִלַּת הָעוֹלָם אַךְ לֹא יִדְרְשׁוּ טוֹבַת צִיּוֹן׃","en":"He commandeth that there shall be no priestcrafts; for, behold, priestcrafts are that men preach and set themselves up for a light unto the world, that they may get gain and praise of the world; but they seek not the welfare of Zion."},{"d":"2028-03-07","ref":"2 Nephi 26:33","b":"2 Nephi","c":26,"v":33,"he":"כִּי אֵין אַחַת מֵהָרָעוֹת הָאֵלֶּה בָּאָה מֵאֵת יְהוָה כִּי עֹשֶׂה הַטּוֹב בִּבְנֵי הָאָדָם וְלֹא יַעֲשֶׂה דָבָר בִּלְתִּי אִם־בָּרוּר לִבְנֵי־הָאָדָם וְקֹרֵא לְכֻלָּם לָבוֹא אֵלָיו וְלָקַחַת מִטּוּבוֹ וְלֹא יִמְנַע מֵאִישׁ הַבָּא אֵלָיו שָׁחוֹר וְלָבָן עֶבֶד וְחׇפְשִׁי זָכָר וּנְקֵבָה וְזוֹכֵר הַגּוֹיִם וְהַכֹּל שָׁוִים לִפְנֵי אֱלֹהִים גַּם־יְהוּדִי וְגַם־גּוֹי׃","en":"For none of these iniquities come of the Lord; for he doeth that which is good among the children of men; and he doeth nothing save it be plain unto the children of men; and he inviteth them all to come unto him and partake of his goodness; and he denieth none that come unto him, black and white, bond and free, male and female; and he remembereth the heathen; and all are alike unto God, both Jew and Gentile."},{"d":"2028-03-08","ref":"2 Nephi 27:5","b":"2 Nephi","c":27,"v":5,"he":"כִּי הִנֵּה שָׁפַךְ יְהוָה עֲלֵיכֶם רוּחַ תַּרְדֵּמָה כִּי הִנֵּה עֲצַמְתֶּם עֵינֵיכֶם וְאֶת־הַנְּבִיאִים מְאַסְתֶּם וְאֶת־רָאשֵׁיכֶם וְאֶת־הַחֹזִים כִּסָּה מִפְּנֵי עֲוֹנְכֶם׃","en":"For behold, the Lord hath poured out upon you the spirit of deep sleep. For behold, ye have closed your eyes, and ye have rejected the prophets; and your rulers, and the seers hath he covered because of your iniquity."},{"d":"2028-03-09","ref":"2 Nephi 27:6","b":"2 Nephi","c":27,"v":6,"he":"וְהָיָה כִּי יָבִיא יְהוָה אֱלֹהִים לָכֶם אֶת־דִּבְרֵי סֵפֶר וְהָיוּ דִּבְרֵי הַנִּרְדָּמִים׃","en":"And it shall come to pass that the Lord God shall bring forth unto you the words of a book, and they shall be the words of them which have slumbered."},{"d":"2028-03-10","ref":"2 Nephi 28:20","b":"2 Nephi","c":28,"v":20,"he":"כִּי הִנֵּה בַּיּוֹם הַהוּא יִזְעַף בִּלְבַב בְּנֵי־הָאָדָם וִיעוֹרְרֵם לִכְעֹס עַל־הַטּוֹב׃","en":"For behold, at that day shall he rage in the hearts of the children of men, and stir them up to anger against that which is good."},{"d":"2028-03-11","ref":"2 Nephi 28:30","b":"2 Nephi","c":28,"v":30,"he":"כִּי הִנֵּה כֹּה־אָמַר יְהוָה אֱלֹהִים אֶתֵּן לִבְנֵי־הָאָדָם קַו לָקָו צַו לָצָו זְעֵיר שָׁם זְעֵיר שָׁם וְאַשְׁרֵי הַשֹּׁמְעִים לְמִצְוֹתַי וּמַטִּים אֹזֶן לַעֲצָתִי כִּי יִלְמְדוּ חׇכְמָה כִּי לַמְקַבֵּל אֶתֵּן עוֹד וּמֵהָאֹמְרִים יֶשׁ־לָנוּ דַי יִלָּקַח גַּם אֲשֶׁר לָהֶם׃","en":"For behold, thus saith the Lord God: I will give unto the children of men line upon line, precept upon precept, here a little and there a little; and blessed are those who hearken unto my precepts, and lend an ear unto my counsel, for they shall learn wisdom; for unto him that receiveth I will give more; and from them that shall say, We have enough, from them shall be taken away even that which they have."},{"d":"2028-03-12","ref":"2 Nephi 30:10","b":"2 Nephi","c":30,"v":10,"he":"כִּי מְהֵרָה תָבוֹא הָעֵת אֲשֶׁר יַעַשׂ יְהוָה אֱלֹהִים מַחֲלֹקֶת גְּדוֹלָה בָּעָם וְאֶת־הָרְשָׁעִים יַשְׁמִיד וְעַל־עַמּוֹ יַחְמֹל אַף גַּם אִם הַשְׁמֵד יַשְׁמִיד אֶת־הָרְשָׁעִים בָּאֵשׁ׃","en":"For the time speedily cometh that the Lord God shall cause a great division among the people, and the wicked will he destroy; and he will spare his people, yea, even if it so be that he must destroy the wicked by fire."}]});
